<p> useEffect(() => {<br> axios.get('/api/messages')<br> .then(response => {<br> setMessages(response.data);<br> })<br> .catch(error => {<br> console.error(error);<br> });<br> }, []);</p>
<p> const handleSendMessage = () => {<br> axios.post('/api/messages', { message: newMessage })<br> .then(response => {<br> setMessages([...messages, response.data]);<br> setNewMessage('');<br> })<br> .catch(error => {<br> console.error(error);<br> });<br> };</p>
<p> return (<br> </p><div><br> <h1>Chat Support</h1><br> <ul><br> {messages.map((message, index) => (<br> <li>{message.text}</li><br> ))}<br> </ul><br> <input<br> type="text"<br> value={newMessage}<br> onChange={e => setNewMessage(e.target.value)}<br> placeholder="Type a message..."<br> /><br> <button>Send</button><br> </div><br> );<br>};<p></p>
<p>export default ChatSupport;<br>Back-end (Node.js)</p>
<p>const express = require('express');<br>const app = express();<br>const axios = require('axios');</p>
<p>app.use(express.json());</p>
<p>const messages = [];</p>
<p>app.get('/api/messages', (req, res) => {<br> res.json(messages);<br>});</p>
<p>app.post('/api/messages', (req, res) => {<br> const message = req.body.message;<br> messages.push({ text: message });<br> res.json({ text: message });<br>});</p>
<p>app.listen(3000, () => {<br> console.log('Server listening on port 3000');<br>});</p>
